EF = [0] * 256
EB = [0] * 256
ED = [0] * 256

for i in range(256):
    j = ((i << 1) ^ (0x11D if i & 0x80 else 0)) & 255
    EF[i] = j
    EB[i ^ j] = i

    x = i
    for _ in range(8):
        x = (x >> 1) ^ (0xD8018001 if x & 1 else 0)
    ED[i] = x & 0xFFFFFFFF


